-- =====================================================================
-- Mumbai AirPulse: Neon Serverless Postgres Schema & Seed
-- Zindi Google Mumbai Air Quality Forecasting Challenge
-- =====================================================================

DROP TABLE IF EXISTS civic_grap_alerts CASCADE;
DROP TABLE IF EXISTS hourly_telemetry CASCADE;
DROP TABLE IF EXISTS stations_network CASCADE;
DROP TABLE IF EXISTS leaderboard_kpis CASCADE;

CREATE TABLE stations_network (
    station_id TEXT PRIMARY KEY,
    station_name TEXT NOT NULL,
    network_source TEXT NOT NULL,
    latitude DOUBLE PRECISION NOT NULL,
    longitude DOUBLE PRECISION NOT NULL,
    p99_threshold DOUBLE PRECISION NOT NULL,
    is_target BOOLEAN NOT NULL,
    nov11_12_slot6_mean DOUBLE PRECISION,
    nov11_12_slot5_mean DOUBLE PRECISION,
    nov11_12_slot4_mean DOUBLE PRECISION,
    nov11_12_safe_mean DOUBLE PRECISION
);

CREATE TABLE hourly_telemetry (
    station_id TEXT REFERENCES stations_network(station_id),
    hour_start_ist TIMESTAMPTZ NOT NULL,
    actual_pm25 DOUBLE PRECISION,
    slot1_p99 DOUBLE PRECISION,
    slot2_seq DOUBLE PRECISION,
    slot4_regime DOUBLE PRECISION,
    slot5_cams DOUBLE PRECISION,
    slot6_stat DOUBLE PRECISION,
    safe_blend DOUBLE PRECISION,
    blh_m DOUBLE PRECISION,
    wind_speed_ms DOUBLE PRECISION,
    ventilation_index DOUBLE PRECISION,
    wind_recirc_24h DOUBLE PRECISION,
    temp_c DOUBLE PRECISION,
    rh_pct DOUBLE PRECISION,
    cams_pm25 DOUBLE PRECISION,
    cams_aod DOUBLE PRECISION,
    cams_co DOUBLE PRECISION,
    cams_no2 DOUBLE PRECISION,
    PRIMARY KEY (station_id, hour_start_ist)
);

CREATE TABLE leaderboard_kpis (
    sub_id TEXT PRIMARY KEY,
    zindi_code TEXT NOT NULL,
    model_name TEXT NOT NULL,
    window_scored TEXT NOT NULL,
    public_rmse DOUBLE PRECISION NOT NULL,
    priv_lb_mean DOUBLE PRECISION NOT NULL,
    notes TEXT
);

CREATE TABLE civic_grap_alerts (
    id SERIAL PRIMARY KEY,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    station_id TEXT REFERENCES stations_network(station_id),
    persona TEXT NOT NULL,
    severity TEXT NOT NULL,
    directive TEXT NOT NULL
);

